BEGIN;

CREATE TABLE IF NOT EXISTS public.vending_products (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    source_file text NULL,
    source_row_number integer NULL,
    system_product_id text NOT NULL UNIQUE,
    system_product_name text NOT NULL,
    vend_price numeric(10,2) NOT NULL CHECK (vend_price >= 0),
    product_name text NOT NULL,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    updated_at timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT uq_vending_products_source_row UNIQUE (source_file, source_row_number)
);

ALTER TABLE public.vending_products
    ALTER COLUMN source_file DROP NOT NULL,
    ALTER COLUMN source_row_number DROP NOT NULL;

